def countMaxOrSubsets(nums):
    n = len(nums)
    max_or = 0

    # Compute the maximum possible bitwise OR
    for num in nums:
        max_or |= num

    count = 0

    # Enumerate all non-empty subsets using bitmasking
    for mask in range(1, 1 << n):  # 1 to 2^n - 1 (skip empty subset)
        subset_or = 0
        for i in range(n):
            if (mask >> i) & 1:
                subset_or |= nums[i]
        if subset_or == max_or:
            count += 1

    return count
